apply.css:
#root { --sl-background:#f5eddf; --sl-ink:#352b2b; --sl-muted:#77665b; --sl-accent:#b94520; --sl-surface:#fffaf1; --sl-border:#d6c5ae; --sl-radius:2px; background:#f5eddf !important; color:#352b2b !important; font-family:Arial, sans-serif !important; }
#root * { font-family:inherit !important; }
#root :is(h1,h2,h3,[data-sl-heading]) { font-family:Georgia, serif !important; color:#352b2b !important; }
#root [data-sl-muted] { color:#77665b !important; }
#root [data-sl-accent] { color:#b94520 !important; }
#root [data-sl-surface] { background:#fffaf1 !important; color:#352b2b !important; border-color:#d6c5ae !important; border-radius:2px !important; }
#root [data-sl-fill] { background:#b94520 !important; }
